#!/usr/bin/env python3
import base64
import re

def xor_bytes(a, b):
    """XOR two byte strings of equal length"""
    return bytes(x ^ y for x, y in zip(a, b))

def load_ciphertexts():
    """Extract and decode Base64 ciphertexts from assignment.txt"""
    ciphertexts = []
    with open('ctf_files/assignment.txt', 'r') as f:
        content = f.read()
        # Find all Base64-encoded strings (one or more lines ending with =)
        pattern = r'([A-Za-z0-9+/\n]+={1,2}(?!\n[A-Za-z0-9]))'
        matches = re.finditer(pattern, content)
        for match in matches:
            # Clean up any newlines in the Base64 string
            b64_text = match.group(1).replace('\n', '')
            try:
                # Decode Base64 to raw bytes
                decoded = base64.b64decode(b64_text)
                ciphertexts.append(decoded)
            except:
                print(f"Failed to decode: {b64_text[:30]}...")
    return ciphertexts

def main():
    ciphertexts = load_ciphertexts()
    print(f"\nFound {len(ciphertexts)} ciphertexts")

    # Print lengths of all ciphertexts
    print("\nCiphertext lengths:")
    length_groups = {}
    for i, ct in enumerate(ciphertexts):
        length = len(ct)
        print(f"Ciphertext {i}: {length} bytes")
        if length not in length_groups:
            length_groups[length] = []
        length_groups[length].append(i)

    # Print groups of ciphertexts with matching lengths
    print("\nCiphertexts with matching lengths:")
    for length, indices in length_groups.items():
        if len(indices) > 1:
            print(f"Length {length}: ciphertexts {indices}")

if __name__ == '__main__':
    main()

