def find_readable_segments(xored_data, min_length=5):
    segments = []
    current_segment = []
    start_pos = 0

    for i, byte in enumerate(xored_data):
        if 32 <= byte <= 126:  # ASCII printable
            if not current_segment:
                start_pos = i
            current_segment.append(byte)
        else:
            if len(current_segment) >= min_length:
                try:
                    text = bytes(current_segment).decode('ascii')
                    if text.strip() and any(c.isalpha() for c in text):
                        segments.append({
                            'start': start_pos,
                            'length': len(current_segment),
                            'text': text,
                            'score': score_text(text)
                        })
                except:
                    pass
            current_segment = []

    # Handle segment at end of data
    if len(current_segment) >= min_length:
        try:
            text = bytes(current_segment).decode('ascii')
            if text.strip() and any(c.isalpha() for c in text):
                segments.append({
                    'start': start_pos,
                    'length': len(current_segment),
                    'text': text,
                    'score': score_text(text)
                })
        except:
            pass

    return sorted(segments, key=lambda x: x['score'], reverse=True)

def load_ciphertexts():
    with open('/home/ctfplayer/ctf_files/assignment.txt', 'r') as f:
        content = f.read()
        pattern = r'[A-Za-z0-9+/]{20,}={0,2}'
        matches = re.finditer(pattern, content)
        ciphertexts = []
        for match in matches:
            try:
                ct = base64.b64decode(match.group().strip())
                if len(ct) > 10:  # Filter out very short ciphertexts
                    ciphertexts.append(ct)
            except:
                continue
    return ciphertexts

def analyze_xor_pair(ct1, ct2):
    xored = xor_bytes(ct1, ct2)
    segments = find_readable_segments(xored)

    interesting_segments = []
    for segment in segments:
        if segment['score'] > 0.2 and segment['length'] >= 10:
            text = segment['text']
            # Check for interesting keywords
            keywords = ['flag', 'key', 'secret', 'pass', 'token', 'auth', 'cred']
            if any(keyword in text.lower() for keyword in keywords):
                segment['interesting'] = True
            interesting_segments.append(segment)

    return interesting_segments

